smart.css:
.smc-root {
  color: var(--smc-text);
  background: var(--smc-bg);
  font-family: var(--smc-font-body);
  font-size: 16px;
  line-height: 1.8;
}

.smc-root h2,
.smc-root h3 {
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-weight: 700;
  line-height: 1.35;
}

.smc-root h2 { font-size: clamp(23px, 3.5vw, 30px); margin: 36px 0 16px; }
.smc-root h3 { font-size: 18px; margin: 24px 0 10px; }
.smc-root p { margin: 0 0 16px; }
.smc-root a { color: var(--smc-accent); font-weight: 600; text-decoration: underline; }
.smc-root a:hover { color: var(--smc-primary); }

.smc-eyebrow {
  color: var(--smc-accent);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  margin: 0 0 8px;
}

.smc-intro {
  padding: 30px 24px;
  background: color-mix(in srgb, var(--smc-primary) 7%, var(--smc-bg));
  border: 1px solid color-mix(in srgb, var(--smc-primary) 16%, var(--smc-border));
  border-radius: var(--smc-radius);
  margin-bottom: 36px;
}
.smc-intro h2 { margin: 0 0 16px; }
.smc-intro p:last-child { margin-bottom: 0; }

.smc-feature-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 16px;
  margin: 24px 0 36px;
}

.smc-feature-card {
  padding: 22px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}

.smc-feature-number {
  display: inline-block;
  padding: 3px 10px;
  background: color-mix(in srgb, var(--smc-accent) 12%, var(--smc-bg));
  color: var(--smc-accent);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 12px;
}

.smc-feature-card h3 { margin: 0 0 8px; }
.smc-feature-card p { color: var(--smc-muted); margin: 0; }

.smc-note {
  margin: 28px 0;
  padding: 20px;
  background: var(--smc-bg);
  border-left: 4px solid var(--smc-accent);
  border-radius: var(--smc-radius);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}
.smc-note strong { color: var(--smc-primary); display: block; margin-bottom: 6px; }
.smc-note p { margin: 0; color: var(--smc-muted); }

.smc-faq {
  margin: 24px 0;
}
.smc-faq details {
  border-top: 1px solid var(--smc-border);
  padding: 16px 0;
}
.smc-faq details:last-child { border-bottom: 1px solid var(--smc-border); }
.smc-faq summary {
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-weight: 700;
  font-size: 17px;
  cursor: pointer;
}
.smc-faq details p { color: var(--smc-muted); margin: 10px 0 0; }

.smc-related {
  margin-top: 48px;
  padding: 24px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}
.smc-related strong { color: var(--smc-primary); display: block; margin-bottom: 12px; }
.smc-related-links { display: flex; flex-wrap: wrap; gap: 10px 14px; }
.smc-related-links a {
  display: inline-block;
  padding: 8px 16px;
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: 999px;
  text-decoration: none;
  font-size: 14px;
}
.smc-related-links a:hover {
  border-color: var(--smc-primary);
  color: var(--smc-primary);
}

.smc-root.smc-js [data-smc-reveal] {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity .45s ease, transform .45s ease;
}
.smc-root.smc-js [data-smc-reveal].is-visible { opacity: 1; transform: none; }

@container smc (min-width: 650px) {
  .smc-feature-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .smc-intro { padding: 36px 30px; }
}

@container smc (max-width: 420px) {
  .smc-root { font-size: 15px; }
  .smc-intro { padding: 22px 16px; }
}

